const PAGE_STYLE_HASH = createHash("sha256").update(PAGE_STYLE).digest("base64");
const SCENE_SCRIPT = `(function(){var cv=document.getElementById('scene');if(!cv)return;var reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;var ctx=cv.getContext('2d'),w=0,h=0,t=0,raf=null,ptr={x:0.5,y:0.5};function paint(){ctx.clearRect(0,0,w,h);var lines=Math.max(14,Math.round(h/30));var px=ptr.x-0.5,py=ptr.y-0.5;ctx.lineWidth=1;for(var i=0;i<lines;i++){var f=i/lines;var y0=f*(h+140)-70+py*10;var amp=14+22*Math.sin(f*3.1+t*0.04);ctx.beginPath();for(var x=-20;x<=w+20;x+=12){var u=x/w;var y=y0+amp*Math.sin(u*2.2+t*0.07+f*5.4)+amp*0.42*Math.sin(u*5.1-t*0.05+f*2.2)+px*14*(0.4+f);if(x===-20)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.strokeStyle='rgba(16,18,22,'+(0.028+0.046*Math.abs(f-0.5)*2).toFixed(3)+')';ctx.stroke();}}function size(){var dpr=Math.min(devicePixelRatio||1,2);w=cv.clientWidth;h=cv.clientHeight;cv.width=Math.round(w*dpr);cv.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);paint();}function frame(){t+=1/60;paint();raf=requestAnimationFrame(frame);}addEventListener('resize',size,{passive:true});addEventListener('pointermove',function(e){ptr.x=e.clientX/innerWidth;ptr.y=e.clientY/innerHeight;},{passive:true});addEventListener('keydown',function(e){if(e.key==='/'&&document.activeElement&&document.activeElement.tagName!=='INPUT'){var i=document.querySelector('.find__in');if(i){e.preventDefault();i.focus();}}});document.addEventListener('visibilitychange',function(){if(reduce)return;if(document.hidden){cancelAnimationFrame(raf);raf=null;}else if(!raf)raf=requestAnimationFrame(frame);});size();if(!reduce)raf=requestAnimationFrame(frame);})();`;
const SCENE_SCRIPT_HASH = createHash("sha256").update(SCENE_SCRIPT).digest("base64");
const CONTENT_SECURITY_POLICY = [
  "default-src 'none'",
  `style-src 'sha256-${PAGE_STYLE_HASH}'`,
  `script-src 'sha256-${SCENE_SCRIPT_HASH}'`,
  "img-src 'self'",
  "base-uri 'none'",
  "form-action 'self'",
  "frame-ancestors 'none'"
].join("; ");

function escapeHtml(value: unknown): string {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function pageShell(title: string, body: string, view: "search" | "agent" | "page" = "page"): string {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Sinetti reputation</title>
  <link rel="icon" href="/favicon.svg" type="image/svg+xml">
  <style>${PAGE_STYLE}</style>
</head>
<body data-view="${view}">
<canvas id="scene" aria-hidden="true"></canvas>
<div class="veil" aria-hidden="true"></div>
<div class="reach" aria-hidden="true"></div>
<div class="shell">
  <header class="bar"><a class="bar__mark" href="/">${MARK_SVG} Sinetti</a><nav aria-label="Primary" class="bar__r"><a class="lbm mu" href="/">Reputation</a></nav></header>
  <main class="mid">${body}</main>
  <footer class="foot"><a class="lbm mu" href="/llms.txt">For agents</a><a class="lbm mu" href="/terms">Terms &amp; privacy</a></footer>
</div>
<script>${SCENE_SCRIPT}</script>
</body>
</html>`;
}

function percentage(value: number): string {
  return `${(value * 100).toFixed(1)}%`;
}

function tierLabel(tier: PublicReputationCard["trust_tier"]): string {
  return tier.replaceAll("_", " ");
}

function settledDate(iso: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toISOString().slice(0, 10);
}

function shortAddress(address: string): string {
  if (address.length < 12) return address;
  return `${address.slice(0, 6)}\u2026${address.slice(-4)}`;
}

/** Rows inside a card. Values are escaped; pass `raw: true` for markup built here. */
function rows(entries: Array<[string, unknown] | [string, string, true]>): string {
  if (entries.length === 0) return "";
  return `<div class="bub__rows">${entries.map(([label, value, raw]) =>
    `<div><span>${escapeHtml(label)}</span><span class="mu">${raw ? value : escapeHtml(value)}</span></div>`
  ).join("")}</div>`;
}

function card(kind: string, body: string, hero = false): string {
  return `<article class="bub${hero ? " bub--hero" : ""}"><span class="lbm mu bub__k">${escapeHtml(kind)}</span>${body}</article>`;
}

function big(value: unknown, caption: string): string {
  return `<span class="bub__big">${escapeHtml(value)}</span><span class="lbm mu bub__cap">${escapeHtml(caption)}</span>`;
}

function settlementMark(cardData: PublicReputationCard): string {
  const marks: Array<"release" | "refund" | "slash"> = [
    ...Array.from({ length: cardData.outcomes.release }, () => "release" as const),
    ...Array.from({ length: cardData.outcomes.refund }, () => "refund" as const),
    ...Array.from({ length: cardData.outcomes.refund_and_slash }, () => "slash" as const)
  ];
  const total = marks.length;
  const slashed = cardData.outcomes.refund_and_slash;
  if (total === 0) return big(0, "settled deals");
  const caption = `<span class="lbm mu bub__cap">${total} settled · <span class="acc">${slashed} slashed</span>. Ticks grouped by outcome.</span>`;
  if (total > 96) {
    return `<span class="bub__big">${total}</span>${caption}${rows([
      ["Released", cardData.outcomes.release],
      ["Refunded", cardData.outcomes.refund],
      ["Refunded and slashed", slashed]
    ])}`;
  }
  const radius = 64;
  const cx = 88;
  const cy = 88;
  const lines = [`<circle cx="88" cy="88" r="47" fill="none" stroke="currentColor" opacity=".18"/>`];
  for (let i = 0; i < total; i += 1) {
    const angle = (i / total) * Math.PI * 2 - Math.PI / 2;
    const slash = marks[i] === "slash";
    const r0 = slash ? radius + 4 : radius - 12;
    const r1 = slash ? radius + 15 : radius;
    const opacity = slash ? "1" : marks[i] === "refund" ? ".38" : ".62";
    lines.push(
      `<line x1="${(cx + Math.cos(angle) * r0).toFixed(1)}" y1="${(cy + Math.sin(angle) * r0).toFixed(1)}" x2="${(cx + Math.cos(angle) * r1).toFixed(1)}" y2="${(cy + Math.sin(angle) * r1).toFixed(1)}" stroke="${slash ? "#D9A441" : "currentColor"}" stroke-opacity="${opacity}" stroke-width="${slash ? "2.4" : "1.6"}"/>`
    );
  }
  return `<svg class="ag__ring" viewBox="0 0 176 176" role="img" aria-label="${total} settled deals, ${slashed} refunded and slashed">${lines.join("")}<text class="ag__n" x="88" y="84" text-anchor="middle" fill="currentColor">${total}</text><text class="ag__u" x="88" y="104" text-anchor="middle" fill="currentColor">settled</text></svg>${caption}`;
}

function shareDonut(share: number, label: string): string {
  const radius = 30;
  const circumference = 2 * Math.PI * radius;
  const pct = Math.max(0, Math.min(1, share));
  return `<svg width="76" height="76" viewBox="0 0 76 76" role="img" aria-label="${percentage(pct)} ${escapeHtml(label)}"><circle cx="38" cy="38" r="30" fill="none" stroke="currentColor" stroke-opacity=".18" stroke-width="6"/><circle cx="38" cy="38" r="30" fill="none" stroke="currentColor" stroke-width="6" stroke-dasharray="${(circumference * pct).toFixed(1)} ${circumference.toFixed(1)}" transform="rotate(-90 38 38)" stroke-linecap="butt"/></svg>`;
}

const WASH_TRADING_CAVEAT = "Settled-deal history is wash-tradeable in principle: cooperating wallets can cheaply settle deals among themselves to farm a clean record. Trust tiers and the independent-counterparty share discount clustered activity, which raises the cost of farming without eliminating it. Read scorecards with counterparty diversity in mind.";


function walletCards(cardData: PublicReputationCard): string {
  return `<div class="bubs">
    ${card("Settlement record", settlementMark(cardData), true)}
    ${card("Outcomes", `${big(percentage(cardData.rates.success_rate), "released of settled")}${rows([
      ["Released", cardData.outcomes.release],
      ["Refunded", cardData.outcomes.refund],
      ["Refunded and slashed", cardData.outcomes.refund_and_slash],
      ["Dispute rate", percentage(cardData.rates.dispute_rate)],
      ["Timeout rate", percentage(cardData.rates.timeout_rate)]
    ])}`)}
    ${card("Counterparties", `${shareDonut(cardData.graph.independent_counterparty_share, "independent counterparties")}${big(cardData.graph.distinct_counterparties, "distinct counterparties")}${rows([
      ["Independent share", percentage(cardData.graph.independent_counterparty_share)],
      ["Repeat counterparty", cardData.repeat_counterparty ? "Yes" : "No"]
    ])}`)}
    ${card("Identity", `${big(tierLabel(cardData.trust_tier), "trust tier")}${rows([
      ["Address", cardData.address],
      ["First settled", settledDate(cardData.started_at)],
      ["Deals with identity anchor", cardData.identity_anchor.deals_with_anchor],
      ["Deals without", cardData.identity_anchor.deals_without_anchor]
    ])}`)}
    ${card("Bonds", `${big(cardData.bonds.posted_count, "Bonds posted")}${rows([
      ["Bonds slashed", cardData.bonds.slashed_count],
      ["Bonds returned", cardData.bonds.returned_count]
    ])}`)}
    ${card("Participation", `${big(cardData.roles.as_seller, "Deals as seller")}${rows([
      ["Deals as buyer", cardData.roles.as_buyer]
    ])}`)}
    ${card("Provenance", `${big(cardData.provenance.operator_verified, "operator-verified settlements")}${rows([
      ["Self adjudicated", cardData.provenance.self_adjudicated]
    ])}`)}
  </div>`;
}

function walletPage(cardData: PublicReputationCard): string {
  return pageShell("Wallet card", `<div class="prof">
    <header class="prof__h">
      <span class="lbm mu">Settlement evidence</span>
      <h1 class="st address" title="${escapeHtml(cardData.address)}">${escapeHtml(shortAddress(cardData.address))}</h1>
      <span class="lbm mu">${escapeHtml(tierLabel(cardData.trust_tier))}</span>
      <a class="back" href="/">New search <kbd>/</kbd></a>
    </header>
    <p class="lbm mu caveat">Computed from settled Sinetti escrow events. Anyone can recompute it from public chain data.</p>
    ${walletCards(cardData)}
  </div>`, "agent");
}

const FILE_STATUS_LABELS: Record<FileStatus, string> = {
  pending: "not read yet",
  ok: "read",
  no_uri: "no URI given",
  scheme_refused: "URI scheme refused",
  private_host: "private host refused",
  too_large: "over 64 KB, refused",
  unreachable: "unreachable",
  hash_mismatch: "hash mismatch",
  invalid_json: "not a JSON object"
};
/** Labelled when known; the raw status otherwise, since the column has no CHECK constraint. */
function fileStatusLabel(status: string): string {
  return Object.hasOwn(FILE_STATUS_LABELS, status) ? FILE_STATUS_LABELS[status as FileStatus] : status;
}

const FLAG_LABEL: Record<IdentityFlag, [string, string]> = {
  registrations_missing: ["Registrations", "The file does not name this agentId on this registry."],
  card_host_mismatch: ["Card host", "The agent card's own url is on a different host from the declared A2A endpoint."],
  legacy_endpoints_key: ["Schema", "The file uses the older endpoints key; the spec now says services."]
};

function readAt(timestamp: number | null): string {
  if (timestamp === null) return "never";
  return `${new Date(timestamp * 1_000).toISOString().slice(0, 16).replace("T", " ")} UTC`;
}

function yesNo(value: boolean | null): string {
  return value === null ? "unstated" : value ? "yes" : "no";
}

/** A link only for an https URI this service would itself fetch; anything else is shown as text. */
function externalLink(uri: string): string {
  const label = escapeHtml(uri.length > 72 ? `${uri.slice(0, 69)}\u2026` : uri);
  if (uri.startsWith("data:")) return "inline data URI";
  const resolved = resolveFeedbackUri(uri);
  if (!("url" in resolved) || !uri.startsWith("https://")) return label;
  return `<a href="${escapeHtml(uri)}" rel="noopener noreferrer nofollow" title="${escapeHtml(uri)}">${label}</a>`;
}

function declaredCards(identity: IdentityCard | null): string {
  if (!identity) {
    return `<div class="bubs">${card("Registration", big("not indexed", "identity registry not read for this agent yet"))}</div>`;
  }
  const declared = identity.declared;
  const agentCardSummary = identity.card;
  const registration = card("Registration", `${big(
    declared?.active === true ? "active" : declared?.active === false ? "inactive" : "unstated", "declared status"
  )}${rows([
    ["Owner", identity.owner],
    ["Registered", settledDate(new Date(identity.registered_at * 1_000).toISOString())],
    ["File", externalLink(identity.agent_uri), true],
    ["File status", `${fileStatusLabel(identity.file_status)}, read ${readAt(identity.fetched_at)}`],
    ...(declared?.supported_trust.length ? [["Supported trust", declared.supported_trust.join(", ")] as [string, unknown]] : []),
    ...(declared?.image ? [["Image", externalLink(declared.image), true] as [string, string, true]] : [])
  ])}`);
  const services = card("Services", declared?.services.length
    ? `${big(declared.services.length, "declared endpoints")}${rows(declared.services.map((service) =>
      [`${service.name}${service.version ? ` ${service.version}` : ""}`, externalLink(service.endpoint), true] as [string, string, true]))}`
    : big(0, "declared endpoints"));
  let agentCardBlock: string;
  if (agentCardSummary) {
    agentCardBlock = card("Agent card", `${big(agentCardSummary.skills.length, "skills declared")}${rows([
      ["Name", agentCardSummary.name ?? "unstated"],
      ["Provider", agentCardSummary.provider?.organization ?? "unstated"],
      ["Version", agentCardSummary.version ?? "unstated"],
      ["A2A protocol", agentCardSummary.protocol_version ?? "unstated"],
      ["Streaming", yesNo(agentCardSummary.capabilities.streaming)],
      ["Push notifications", yesNo(agentCardSummary.capabilities.push_notifications)],
      ["Security schemes", agentCardSummary.security_schemes.join(", ") || "none listed"],
      ["Signatures", agentCardSummary.signed ? "present, unverified here" : "none"],
      ["Card", externalLink(identity.card_url ?? ""), true],
      ["Read", readAt(identity.card_fetched_at)]
    ])}`);
  } else if (identity.card_url) {
    agentCardBlock = card("Agent card", `${big("unread", "agent card")}${rows([
      ["Card", externalLink(identity.card_url), true],
      ["Status", `${identity.card_status ? fileStatusLabel(identity.card_status) : "not read yet"}, read ${readAt(identity.card_fetched_at)}`]
    ])}`);
  } else {
    agentCardBlock = card("Agent card", big("none", "no A2A service declared"));
  }
  const SHOWN_SKILLS = 12;
  const skillList = agentCardSummary?.skills ?? [];
  const skills = skillList.length
    ? card("Skills", rows([
      ...skillList.slice(0, SHOWN_SKILLS).map((skill) => [skill.name ?? skill.id, skill.tags.slice(0, 3).join(", ") || skill.id] as [string, unknown]),
      ...(skillList.length > SHOWN_SKILLS ? [[`${skillList.length - SHOWN_SKILLS} more`, "on the agent card"] as [string, unknown]] : [])
    ]))
    : "";
  const flags = identity.flags.length
    ? card("Flags", rows(identity.flags.map((flag) => FLAG_LABEL[flag] as [string, unknown])))
    : "";
  return `${declared?.description ? `<p class="desc">${escapeHtml(declared.description)}</p>` : ""}
    <div class="bubs">${registration}${services}${agentCardBlock}${skills}${flags}</div>`;
}

function agentPage(registryName: string, cardData: AgentCard): string {
  const unverified = cardData.feedback.total - cardData.feedback.verified;
  const title = cardData.identity?.declared?.name ?? `Agent #${cardData.agent_id}`;
  const entries = cardData.entries.map((entry) => card("Verified entry", `${big(
    entry.value_decimals ? `${entry.value}e-${entry.value_decimals}` : entry.value, `rated by ${shortAddress(entry.client)}`
  )}${rows([
    ["Rater", entry.client],
    ["Deal", `${entry.evidence.dealId} on eip155:${entry.evidence.chainId}`],
    ["Escrow", entry.evidence.contract],
    ["Outcome", entry.evidence.resolution.replaceAll("_", " ")],
    ["Rater was", entry.evidence.clientRole],
    ["Settled", settledDate(new Date(entry.evidence.settledAt * 1_000).toISOString())],
    ...(entry.skills.length ? [["Skill", entry.skills.map((skill) => skill.name ?? `${skill.id} (not on the agent card)`).join(", ")] as [string, unknown]] : []),
    ...(entry.task_id ? [["Task", entry.task_id] as [string, unknown]] : []),
    ["Agent wallet", `<a href="/a/${escapeHtml(entry.evidence.agentAddress)}">${escapeHtml(shortAddress(entry.evidence.agentAddress))}</a>`, true]
  ])}`)).join("");
  return pageShell(title, `<div class="prof">
    <header class="prof__h">
      <span class="lbm mu">${escapeHtml(registryName)}</span>
      <h1 class="st">${escapeHtml(title)}</h1>
      <span class="lbm mu">#${escapeHtml(cardData.agent_id)}</span>
      <span class="lbm mu address">${escapeHtml(cardData.registry)}</span>
      <a class="back" href="/">New search <kbd>/</kbd></a>
    </header>
    <span class="lbm mu sect">Declared by the agent. Read from its registration file and agent card, unchecked.</span>
    ${declaredCards(cardData.identity)}
    <span class="lbm mu sect">Ratings. Verified means the rater proved a settled deal with this agent; the rest are counted.</span>
    <div class="bubs">
      ${card("Verified feedback", `${shareDonut(cardData.feedback.total ? cardData.feedback.verified / cardData.feedback.total : 0, "of entries verified")}${big(cardData.feedback.verified, `of ${cardData.feedback.total} entries verified by settlement`)}`, true)}
      ${card("Verified score", `${big(cardData.verified_score === null ? "none" : cardData.verified_score.toFixed(1), "mean of verified entries")}${rows([
        ["Verified raters", cardData.verified_clients.length]
      ])}`)}
      ${card("Unverified", `${big(unverified, "entries counted, kept out of the score")}${rows([
        ["Revoked", cardData.feedback.revoked],
        ["Not yet checked", cardData.feedback.unchecked],
        ["Repeat citations of one deal", cardData.feedback.duplicates]
      ])}`)}
    </div>
    ${entries ? `<div class="bubs">${entries}</div>` : `<p class="lbm mu caveat">No verified entries. No rating about this agent names a settled deal between the rater and the agent.</p>`}
  </div>`, "agent");
}

function directoryRows(registryName: string, agents: DirectoryRow[]): string {
  return `<div class="dir">${agents.map((agent) =>
    `<a href="/r/${escapeHtml(registryName)}/${escapeHtml(agent.agent_id)}"${agent.active === false ? ' class="dim"' : ""}>
      <span>${escapeHtml(agent.name ?? `Agent #${agent.agent_id}`)}</span>
      <span class="lbm mu">#${escapeHtml(agent.agent_id)}${agent.active === false ? " · inactive" : ""}${agent.file_status !== "ok" ? ` · file ${escapeHtml(fileStatusLabel(agent.file_status))}` : ""}</span>
      <span class="lbm mu">${agent.verified} verified of ${agent.total}</span>
    </a>`).join("")}</div>`;
}

function registryPage(registryName: string, caip10: string, verified: ReturnType<typeof listVerifiedAgents>, directory: ReturnType<typeof listAgentDirectory>): string {
  const pager = directory.pages > 1 ? `<nav class="pager lbm mu" aria-label="Directory pages">
      ${directory.page > 1 ? `<a href="/r/${escapeHtml(registryName)}?page=${directory.page - 1}">Previous</a>` : ""}
      <span>Page ${directory.page} of ${directory.pages}</span>
      ${directory.page < directory.pages ? `<a href="/r/${escapeHtml(registryName)}?page=${directory.page + 1}">Next</a>` : ""}
    </nav>` : "";
  return pageShell("Registry", `<div class="prof">
    <header class="prof__h">
      <span class="lbm mu">${escapeHtml(registryName)}</span>
      <h1 class="st">Registry</h1>
      <span class="lbm mu address">${escapeHtml(caip10)}</span>
      <a class="back" href="/">New search <kbd>/</kbd></a>
    </header>
    <span class="lbm mu sect">Verified. Agents with at least one rating that names a settled deal.</span>
    ${verified.length === 0 ? `<p class="lbm mu caveat">None yet. A rating verifies when its file names a settled escrow deal between the rater and the agent, and no entry on this registry names one so far.</p>` : `<div class="bubs">${verified.map((agent) =>
      card("Agent", `${big(agent.name ?? `#${agent.agent_id}`, `${agent.verified} verified of ${agent.total}`)}${rows([
        ["Card", `<a href="/r/${escapeHtml(registryName)}/${escapeHtml(agent.agent_id)}">open</a>`, true]
      ])}`)
    ).join("")}</div>`}
    <span class="lbm mu sect">Directory. Every agent registered here, by the name it declares. Most verified first.</span>
    ${directory.agents.length === 0 ? `<p class="lbm mu caveat">No registrations indexed yet.</p>` : directoryRows(registryName, directory.agents)}
    ${pager}
  </div>`, "agent");
}

function searchPage(query: string, results: Array<{ registry: RegistryConfig; agents: DirectoryRow[] }>): string {
  const total = results.reduce((sum, entry) => sum + entry.agents.length, 0);
  return pageShell("Search", `<div class="prof">
    <header class="prof__h">
      <span class="lbm mu">Name search</span>
      <h1 class="st">${escapeHtml(query)}</h1>
      <span class="lbm mu">${total} ${total === 1 ? "match" : "matches"}</span>
      <a class="back" href="/">New search <kbd>/</kbd></a>
    </header>
    <p class="lbm mu caveat">Names are declared by agents and are not unique. Check the agentId and the verified count.</p>
    ${total === 0 ? `<p class="lbm mu caveat">No declared name contains this text on any indexed registry.</p>` : results.filter((entry) => entry.agents.length).map((entry) =>
      `<span class="lbm mu sect">${escapeHtml(entry.registry.name)}</span>${directoryRows(entry.registry.name, entry.agents)}`).join("")}
  </div>`, "agent");
}

function homePage(): string {
  const registries = Object.keys(KNOWN_REGISTRIES).map((name) => `<a href="/r/${escapeHtml(name)}">${escapeHtml(name)}</a>`).join(" · ");
  return pageShell("Home", `<div class="find">
    <span class="lbm mu find__lede">Attested feedback for ERC-8004. Look up one agent by name, address, or registry/agentId.</span>
    <form class="find__box" method="GET" action="/lookup">
      <label class="sr" for="q">Agent address, or registry/agentId</label>
      <input class="find__in" id="q" name="q" type="text" autocomplete="off" spellcheck="false" required placeholder="name, 0x address, or ethereum-sepolia/42">
      <span class="lbm mu find__key">/</span>
      <button class="sr" type="submit">Look up</button>
    </form>
    <span class="lbm mu find__note">Ratings whose rater can prove a settled escrow deal with the agent count. The rest are shown and kept out of the score. Read-only API, needs no account, no signature, and no session: <code>/registries/{registry}/agents/{agentId}</code>, <code>/registries/{registry}/search?q=</code>, <code>/agents/{address}</code>. Registries: ${registries}.</span>
  </div>`, "search");
}

function notFoundPage(): string {
  return pageShell("Not found", `<div class="prof"><header class="panel"><h1>Card not found</h1><p>No wallet with settled Sinetti deals, and no known registry and agentId with an indexed registration or rating, matches this.</p></header></div>`);
}

