// Served from the repository root so the file a GitHub visitor reads and the one an agent fetches are one document.
const LLMS_DOCUMENT = readFileSync(resolve(process.cwd(), "llms.txt"), "utf8");
function knownRegistry(name: string) {
  if (!Object.hasOwn(KNOWN_REGISTRIES, name)) return null;
  return { ...KNOWN_REGISTRIES[name], rpcUrl: "", confirmations: 0 };
}

export function registerWebRoutes(app: Express, db: SinettiDatabase): void {
  const router = express.Router();
  router.use((_request, response, next) => {
    response.setHeader("Content-Security-Policy", CONTENT_SECURITY_POLICY);
    next();
  });

  router.get("/favicon.svg", (_request, response) => {
    response.setHeader("Cache-Control", "public, max-age=86400");
    response.type("image/svg+xml").send(FAVICON_SVG);
  });
  router.get("/favicon.ico", (_request, response) => {
    response.redirect(302, "/favicon.svg");
  });

  router.get("/", (_request, response) => {
    response.type("html").send(homePage());
  });

  // One box for every kind of card: a wallet address, `registry/agentId`, or a declared name.
  router.get("/lookup", (request, response) => {
    const raw = typeof request.query.q === "string" ? request.query.q.trim() : "";
    const agent = raw.match(/^([a-z0-9-]+)\/([0-9]{1,78})$/);
    if (agent && knownRegistry(agent[1])) {
      response.redirect(302, `/r/${agent[1]}/${agent[2]}`);
      return;
    }
    if (/^0x[0-9a-fA-F]{40}$/.test(raw)) {
      try {
        response.redirect(302, `/a/${getAddress(raw)}`);
        return;
      } catch {
        response.status(404).type("html").send(notFoundPage());
        return;
      }
    }
    if (!raw) {
      response.status(404).type("html").send(notFoundPage());
      return;
    }
    response.redirect(302, `/search?q=${encodeURIComponent(raw)}`);
  });

  // Declared names across every known registry. One exact match opens the card.
  router.get("/search", (request, response) => {
    const query = typeof request.query.q === "string" ? request.query.q.trim().slice(0, 120) : "";
    if (!query) {
      response.status(404).type("html").send(notFoundPage());
      return;
    }
    const results = Object.keys(KNOWN_REGISTRIES).map((name) => {
      const registry = knownRegistry(name)!;
      return { registry, agents: searchAgents(db, registry, query) };
    });
    const exact = results.flatMap((entry) => agentsNamed(db, entry.registry, query)
      .map((agentId) => ({ registry: entry.registry.name, agentId })));
    if (exact.length === 1) {
      response.redirect(302, `/r/${exact[0].registry}/${exact[0].agentId}`);
      return;
    }
    response.type("html").send(searchPage(query, results));
  });

  router.get("/a/:address", (request, response) => {
    let address: string;
    try {
      address = getAddress(request.params.address);
    } catch {
      response.status(404).type("html").send(notFoundPage());
      return;
    }
    const cardData = aggregateReputation(db, address);
    if (!cardData) {
      response.status(404).type("html").send(notFoundPage());
      return;
    }
    response.type("html").send(walletPage(publicCard(cardData)));
  });

  router.get("/r/:name", (request, response) => {
    const registry = knownRegistry(request.params.name);
    if (!registry) {
      response.status(404).type("html").send(notFoundPage());
      return;
    }
    const page = typeof request.query.page === "string" && /^[1-9][0-9]{0,5}$/.test(request.query.page) ? Number(request.query.page) : 1;
    response.type("html").send(registryPage(request.params.name, registryCaip10(registry), listVerifiedAgents(db, registry), listAgentDirectory(db, registry, page)));
  });

  router.get("/r/:name/:agentId", (request, response) => {
    const registry = knownRegistry(request.params.name);
    const agentId = request.params.agentId;
    const cardData = registry && /^[0-9]{1,78}$/.test(agentId) ? agentCard(db, registry, agentId) : null;
    if (!cardData) {
      response.status(404).type("html").send(notFoundPage());
      return;
    }
    response.type("html").send(agentPage(request.params.name, cardData));
  });

  router.get("/llms.txt", (_request, response) => {
    response.type("text/plain; charset=utf-8").send(LLMS_DOCUMENT);
  });

  router.get("/terms", (_request, response) => {
    response.type("html").send(termsAndPrivacyPage());
  });

  app.use(router);
}
